public class QuorumClusterNode {
    private final int totalVotingNodes;
    private final Set<String> activePeers;

    public QuorumClusterNode(int totalVotingNodes) {
        this.totalVotingNodes = totalVotingNodes;
        this.activePeers = ConcurrentHashMap.newKeySet();
    }

    public boolean hasQuorum() {
        int requiredQuorum = (totalVotingNodes / 2) + 1;
        // Include self (+1) in the active cluster count calculation
        int currentVotes = activePeers.size() + 1;
        return currentVotes >= requiredQuorum;
    }

    public void handleHeartbeat(String peerId, boolean isAlive) {
        if (isAlive) {
            activePeers.add(peerId);
        } else {
            activePeers.remove(peerId);
        }
    }
}
